+package com.example.contact;
+
+import static org.junit.jupiter.api.Assertions.*;
+
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    private TextField name() { return $(TextField.class).withLabel("Name").single(); }
+    private EmailField email() { return $(EmailField.class).withLabel("Email").single(); }
+    private TextField phone() { return $(TextField.class).withLabel("Phone").single(); }
+    private TextArea message() { return $(TextArea.class).withLabel("Message").single(); }
+    private Button send() { return $(Button.class).withText("Send").single(); }
+
+    @SuppressWarnings("unchecked")
+    private Grid<ContactMessage> grid() { return $(Grid.class).single(); }
+
+    @Test
+    void initialState() {
+        navigate(ContactView.class);
+        assertEquals("Contact", $(H1.class).single().getText());
+        assertTrue(name().isEmpty() && email().isEmpty() && phone().isEmpty() && message().isEmpty());
+        assertTrue(send().isEnabled());
+        assertEquals("About", $(RouterLink.class).single().getText());
+    }
+
+    @Test
+    void emptyFormShowsErrors() {
+        navigate(ContactView.class);
+        int rows = test(grid()).size();
+        test(send()).click();
+        assertTrue(name().isInvalid());
+        assertEquals("Name is required", name().getErrorMessage());
+        assertEquals("Give an e-mail address or a phone number", email().getErrorMessage());
+        assertTrue(email().isInvalid());
+        assertEquals("Message is required", message().getErrorMessage());
+        assertTrue(message().isInvalid());
+        assertEquals(rows, test(grid()).size());
+        assertTrue($(Notification.class).all().isEmpty());
+    }
+
+    @Test
+    void invalidEmailAndLongMessage() {
+        navigate(ContactView.class);
+        test(name()).setValue("X");
+        test(email()).setValue("not-an-email");
+        test(message()).setValue("a".repeat(501));
+        test(send()).click();
+        assertFalse(name().isInvalid());
+        assertEquals("Enter a valid e-mail address", email().getErrorMessage());
+        assertTrue(email().isInvalid());
+        assertEquals("Message must be at most 500 characters", message().getErrorMessage());
+        assertEquals("not-an-email", email().getValue());
+    }
+
+    @Test
+    void sendWithPhoneOnlyViaEnter() {
+        navigate(ContactView.class);
+        test(name()).setValue("Phone Person");
+        test(phone()).setValue("12345");
+        test(message()).setValue("Hello by phone");
+        fireShortcut(Key.ENTER);
+        assertTrue(test($(Notification.class).last()).getText().contains("Message sent"));
+        assertEquals("Phone Person", test(grid()).getRow(0).name());
+        assertTrue(name().isEmpty() && phone().isEmpty() && message().isEmpty());
+        assertFalse(send().isEnabled());
+        test(name()).setValue("a");
+        assertTrue(send().isEnabled());
+
+        // persists across navigation
+        test(name()).setValue("");
+        navigate(AboutView.class);
+        navigate(ContactView.class);
+        assertEquals("Phone Person", test(grid()).getRow(0).name());
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void leaveWithoutInputNoDialog() {
+        navigate(ContactView.class);
+        test($(RouterLink.class).single()).click();
+        assertEquals("About", $(H1.class).single().getText());
+    }
+
+    @Test
+    void leaveWithInputAsks() {
+        navigate(ContactView.class);
+        test(email()).setValue("a@b.com");
+        test($(RouterLink.class).single()).click();
+        assertTrue(getCurrentView() instanceof ContactView);
+        test($(Button.class).withText("Keep editing").single()).click();
+        assertTrue(getCurrentView() instanceof ContactView);
+        assertEquals("a@b.com", email().getValue());
+        assertTrue($(Dialog.class).all().stream().noneMatch(Dialog::isOpened));
+
+        com.vaadin.flow.component.UI.getCurrent().navigate(AboutView.class);
+        assertTrue(getCurrentView() instanceof ContactView);
+        assertEquals(1, $(Dialog.class).all().stream().filter(Dialog::isOpened).count());
+        test($(Button.class).withText("Discard").single()).click();
+        assertTrue(getCurrentView() instanceof AboutView);
+    }
+}
